export function renderPlainTemplate(template: string, values: Record<string, string>) {
  return template.replace(/\{\{([a-zA-Z0-9_]+)\}\}/g, (_, key: string) => {
    if (!Object.hasOwn(values, key)) throw new Error('누락된 변수: ' + key);
    return values[key];
  });
}
