type SignatureRequest = { documentVersion: string; expiresAt: number; revoked: boolean };
export function canOpen(request: SignatureRequest, version: string, now: number) {
  return !request.revoked && request.documentVersion === version
    && now < request.expiresAt;
}
// 서명자의 권한과 본인확인, 서명 증빙 생성은 서버·서명 서비스에서 처리합니다.

type Signer = { order: number; status: 'pending' | 'signed' | 'declined' };
export function activeSigners(signers: Signer[]) {
  if (signers.some(s => s.status === 'declined')) return [];
  const pending = signers.filter(s => s.status === 'pending');
  const order = Math.min(...pending.map(s => s.order));
  return pending.filter(s => s.order === order);
}

type OcrWord = { text: string; confidence: number };
export function reviewWords(words: OcrWord[], threshold: number) {
  return words.map(word => ({ ...word,
    needsReview: !Number.isFinite(word.confidence) || word.confidence < threshold
  }));
}
// confidence 범위는 OCR 엔진별 문서에 맞춰 정하고 중요한 값은 별도로 검토합니다.

export async function sha256Hex(file: Blob) {
  const digest = await crypto.subtle.digest('SHA-256', await file.arrayBuffer());
  return [...new Uint8Array(digest)]
    .map(byte => byte.toString(16).padStart(2, '0')).join('');
}
